    (2, 'title2', 'content2', 'short2', 'img_src', 'imalt2', 'link_fb2', 'link_lkd2', 2, 1,    '2025-04-18 20:14:49', '2025-04-18 20:14:49', NULL, 'draft', NULL, NULL, NULL);

-- L'identity ne connait pas les ids inseres explicitement, on la recale
SELECT setval(pg_get_serial_sequence('posts', 'id'), (SELECT MAX(id) FROM posts));
